from repair import *
P='MMA cavernous left';original,faces=mesh(P);rr=rims(original,faces);target=rr[1];ed=np.unique(np.sort(np.vstack([faces[:,[0,1]],faces[:,[1,2]],faces[:,[2,0]]]),1),axis=0);lens=np.linalg.norm(original[ed[:,0]]-original[ed[:,1]],axis=1);G=coo_matrix((np.r_[lens,lens],(np.r_[ed[:,0],ed[:,1]],np.r_[ed[:,1],ed[:,0]])),shape=(len(original),len(original))).tocsr();dist=dijkstra(G,indices=target,min_only=True)
def adjust(delta,support=2.):
 vertices,inv=np.unique(original,axis=0,return_inverse=True);tri=inv[faces];ee=np.unique(np.sort(np.vstack([tri[:,[0,1]],tri[:,[1,2]],tri[:,[2,0]]]),1),axis=0);ee=ee[ee[:,0]!=ee[:,1]];ll=np.linalg.norm(vertices[ee[:,0]]-vertices[ee[:,1]],axis=1);gg=coo_matrix((np.r_[ll,ll],(np.r_[ee[:,0],ee[:,1]],np.r_[ee[:,1],ee[:,0]])),shape=(len(vertices),len(vertices))).tocsr();tt=np.unique(inv[target]);dd=dijkstra(gg,indices=tt,min_only=True);fixed=np.unique(np.r_[np.flatnonzero(dd>=support),inv[rr[0]],inv[rr[2]]]);assert not np.intersect1d(tt,fixed).size;boundary=np.unique(np.r_[fixed,tt]);free=np.setdiff1d(np.arange(len(vertices)),boundary);weights=1/np.maximum(ll,1e-5);aa=coo_matrix((np.r_[weights,weights],(np.r_[ee[:,0],ee[:,1]],np.r_[ee[:,1],ee[:,0]])),shape=gg.shape).tocsr();lap=diags(np.asarray(aa.sum(1)).ravel())-aa;u=np.zeros(len(vertices));u[tt]=1;u[free]=spsolve(lap[free][:,free],-lap[free][:,boundary]@u[boundary]);return (original+u[inv,None]*np.array(delta)).astype('<f4').astype(float)
if __name__=='__main__':
 b,bf=mesh('bone.sphenoid');sd=vtk.vtkImplicitPolyDataDistance();sd.SetInput(poly(b,bf));oldfold=intersections(original,faces);history=[]
 for delta in [(0,-.15,0),(0,-.25,0),(0,-.15,.1),(0,-.25,.1),(0,-.4,.1)]:
  p=adjust(delta);a=original[faces];q=p[faces];a=np.cross(a[:,1]-a[:,0],a[:,2]-a[:,0]);q=np.cross(q[:,1]-q[:,0],q[:,2]-q[:,0]);rev=int(np.sum((np.einsum('ij,ij->i',a,q)<=0)&(np.linalg.norm(a,axis=1)>1e-10)));row={'delta':delta,'newSelfIntersections':len(intersections(p,faces)-oldfold),'reversedFaces':rev,'minBonePortClearanceMm':min(sd.EvaluateFunction(x)for x in p[target])};history.append(row);print(row,flush=True)
 (D.parent/'parent-adjust-screen.json').write_text(json.dumps(history,indent=2)+'\n')
